SELECT 
FROM SYS_PARAMETER


        AND PARAMETER_KEY LIKE CONCAT('%', #{queryVO.parameterKey}, '%')


        AND PARAMETER_NAME LIKE CONCAT('%', #{queryVO.parameterName}, '%')


        AND PARAMETER_TYPE = #{queryVO.parameterType}


        AND PARAMETER_GROUP = #{queryVO.parameterGroup}


        AND ENABLED = #{queryVO.enabled}


        AND IS_SYSTEM = #{queryVO.isSystem}


        AND CREATE_BY LIKE CONCAT('%', #{queryVO.createBy}, '%')




                AND DATE(CREATE_TIME) >= #{queryVO.startDate}


                AND TRUNC(CREATE_TIME) >= TO_DATE(#{queryVO.startDate}, 'YYYY-MM-DD')






                AND DATE(CREATE_TIME) <= #{queryVO.endDate}


                AND TRUNC(CREATE_TIME) <= TO_DATE(#{queryVO.endDate}, 'YYYY-MM-DD')




ORDER BY SORT_ORDER ASC, CREATE_TIME DESC

SELECT 
FROM SYS_PARAMETER
WHERE PARAMETER_KEY = #{parameterKey}

    AND PARAMETER_ID != #{excludeId}

LIMIT 1

